app.get('/api/availability/slots',auth,approved,wrap(async(req,res)=>{
 const clinicianId=positive(req.query.clinician_id)?Number(req.query.clinician_id):null;
 const days=Math.min(60,Math.max(1,Number(req.query.days)||14));
 const department=String(req.query.department||'').trim(),specialty=String(req.query.specialty||'').trim();
 const params=[];let filters='';
 if(clinicianId){filters+=' AND u.id=?';params.push(clinicianId)}
 if(department && department.toUpperCase()!=='GOPD'){filters+=' AND u.department=?';params.push(department)}
 if(specialty){filters+=' AND cp.specialty=?';params.push(specialty)}
 const [windows]=await query(`SELECT a.clinician_id,a.starts_at,a.ends_at,u.name clinician FROM availability a JOIN users u ON u.id=a.clinician_id LEFT JOIN clinician_profiles cp ON cp.user_id=u.id WHERE a.active=1 AND a.ends_at>NOW() AND a.starts_at<DATE_ADD(NOW(),INTERVAL ${days} DAY) AND u.status='approved' ${filters}
 UNION ALL
 SELECT sh.clinician_id,sh.starts_at,sh.ends_at,u.name clinician FROM doctor_shifts sh JOIN users u ON u.id=sh.clinician_id LEFT JOIN clinician_profiles cp ON cp.user_id=u.id WHERE sh.status IN ('scheduled','checked_in') AND sh.ends_at>NOW() AND sh.starts_at<DATE_ADD(NOW(),INTERVAL ${days} DAY) AND u.status='approved' AND sh.coverage IN ('online','physical','both') ${filters.replaceAll('a.clinician_id','sh.clinician_id').replaceAll('u.id','u.id')}
 ORDER BY starts_at`,[...params,...params]);
 const [busy]=await query("SELECT clinician_id,starts_at,ends_at FROM appointments WHERE status NOT IN ('cancelled','no_show') AND starts_at<DATE_ADD(NOW(),INTERVAL ? DAY) AND ends_at>NOW()",[days]);
 const seen=new Set(),slots=[];
 for(const w of windows){let cursor=new Date(String(w.starts_at).replace(' ','T')+'Z'),finish=new Date(String(w.ends_at).replace(' ','T')+'Z');while(cursor.getTime()+30*60000<=finish.getTime()){const end=new Date(cursor.getTime()+30*60000),key=Number(w.clinician_id)+'|'+cursor.toISOString();const occupied=busy.some(b=>Number(b.clinician_id)===Number(w.clinician_id)&&new Date(String(b.starts_at).replace(' ','T')+'Z')<end&&new Date(String(b.ends_at).replace(' ','T')+'Z')>cursor);if(!occupied&&cursor>new Date()&&!seen.has(key)){const sql=d=>d.toISOString().slice(0,19).replace('T',' ');slots.push({clinician_id:w.clinician_id,clinician:w.clinician,starts_at:sql(cursor),ends_at:sql(end)});seen.add(key)}cursor=end;}}
 res.json(slots.sort((x,y)=>x.starts_at.localeCompare(y.starts_at)));
}));
