app.patch('/api/availability/:id',auth,approved,allow('admin','support','doctor','consultant'),wrap(async(req,res)=>{const u=getUser(req);const [rows]=await query('SELECT * FROM availability WHERE id=? AND active=1',[req.params.id]);const old=rows[0];if(!old)throw bad(404,'Availability not found');if(['doctor','consultant'].includes(u.role)&&Number(old.clinician_id)!==Number(u.id))throw bad(403,'Doctors can edit only their own availability');const clinicianId=['doctor','consultant'].includes(u.role)?u.id:(positive(req.body.clinician_id)?Number(req.body.clinician_id):Number(old.clinician_id));const starts=req.body.starts_at||String(old.starts_at).slice(0,19),ends=req.body.ends_at||String(old.ends_at).slice(0,19);if(!validDate(starts)||!validDate(ends)||ends<=starts)throw bad(400,'Enter a valid start and end time');const [conflict]=await query('SELECT id FROM availability WHERE clinician_id=? AND id<>? AND active=1 AND starts_at<? AND ends_at>? LIMIT 1',[clinicianId,req.params.id,ends,starts]);if(conflict.length)throw bad(409,'This schedule overlaps another availability window');const [booked]=await query("SELECT id FROM appointments WHERE clinician_id=? AND status NOT IN ('cancelled','no_show') AND starts_at<? AND ends_at>? LIMIT 1",[old.clinician_id,old.ends_at,old.starts_at]);if(booked.length&&(clinicianId!==Number(old.clinician_id)||starts>String(old.starts_at).slice(0,19)||ends<String(old.ends_at).slice(0,19)))throw bad(409,'This availability has appointments. Do not change its time or doctor; create a new schedule instead.');await query('UPDATE availability SET clinician_id=?,starts_at=?,ends_at=? WHERE id=?',[clinicianId,starts,ends,req.params.id]);await audit(req,'availability_updated','availability',req.params.id);res.json({ok:true})}));
