// Direct in-app messaging and user-scoped notifications.
function messagingAllowed(actor, target, linked=false){
 if(!target||Number(actor.id)===Number(target.id))return false;
 if(['admin','support','it'].includes(actor.role))return true;
 const actorClin=['doctor','consultant'].includes(actor.role), targetClin=['doctor','consultant'].includes(target.role);
 if(!actorClin&&targetClin)return true; // any signed-in university user may initiate a message to a clinician
 if(actorClin&&!targetClin)return linked; // clinicians may message only patients/dependants they are assigned to consult
 return false;
}
