app.get('/api/labs/:id/result-documents',auth,approved,wrap(async(req,res)=>{const [rows]=await query("SELECT d.id,d.file_name,d.mime_type,d.created_at,d.uploaded_by,a.patient_id,a.clinician_id FROM lab_result_documents d JOIN lab_orders l ON l.id=d.lab_order_id JOIN appointments a ON a.id=l.appointment_id WHERE l.id=? ORDER BY d.created_at DESC",[req.params.id]);const u=getUser(req);if(!rows.length)return res.json([]);if(!['admin','lab'].includes(u.role)&&!rows.some(r=>Number(r.patient_id)===Number(u.id)||Number(r.clinician_id)===Number(u.id)))throw bad(403,'Not authorized');res.json(rows)}));
