function sendClinicalPdf(res,title,lines,filename){const PDFDocument=require('pdfkit');const pdf=new PDFDocument({size:'A4',margin:48});res.setHeader('Content-Type','application/pdf');res.setHeader('Content-Disposition',`attachment; filename="${filename}"`);pdf.pipe(res);pdf.fontSize(17).font('Helvetica-Bold').text('AZMAN UNIVERSITY HEALTHCONNECT',{align:'center'});pdf.moveDown(.3);pdf.fontSize(15).text(title,{align:'center'});pdf.moveDown();pdf.fontSize(10).font('Helvetica');for(const line of lines){pdf.font('Helvetica-Bold').text(line[0]);pdf.font('Helvetica').text(String(line[1]??'—'));pdf.moveDown(.55);}pdf.moveDown().fontSize(8).fillColor('#555').text('This document was generated from Azman University HealthConnect. Verify patient identity and prescription/test details before use.');pdf.end();}
app.get('/api/prescriptions/:id/download.pdf',auth,approved,wrap(async(req,res)=>{const [rows]=await query("SELECT p.*,a.patient_id,a.dependant_id,a.clinician_id,u.name patient_name,c.name clinician_name FROM prescriptions p JOIN appointments a ON a.id=p.appointment_id JOIN users u ON u.id=a.patient_id JOIN users c ON c.id=p.clinician_id WHERE p.id=?",[req.params.id]);const p=rows[0],u=getUser(req);if(!p)throw bad(404,'Prescription not found');if(!['admin','pharmacy'].includes(u.role)&&Number(p.patient_id)!==Number(u.id)&&Number(p.clinician_id)!==Number(u.id))throw bad(403,'Not authorized');sendClinicalPdf(res,'MEDICAL PRESCRIPTION',[['Patient',p.patient_name],['Prescription reference',p.id],['Prescribing clinician',p.clinician_name],['Medication',p.medication],['Dose',p.dose],['Route',p.route],['Frequency',p.frequency],['Duration',p.duration],['Instructions',p.instructions],['Status',p.status],['Date',p.created_at]],`Azman-prescription-${p.id}.pdf`)}));
