app.post('/api/emergencies',auth,approved,allow('admin','support'),wrap(async(req,res)=>{const {clinician_id,priority,case_summary,location,required_by}=req.body;if(!positive(clinician_id)||!['critical','urgent','routine'].includes(priority)||!text(case_summary)||text(case_summary).length>800||!text(location)||!validDate(required_by))throw bad(400,'Complete emergency details required');const [docs]=await query("SELECT u.id FROM users u WHERE u.id=? AND u.role IN ('doctor','consultant') AND u.status='approved'",[clinician_id]);if(!docs.length)throw bad(400,'Doctor not available in directory');const conn=await pool.getConnection();try{await conn.beginTransaction();const [r]=await conn.execute('INSERT INTO emergency_requests(requested_by,clinician_id,priority,case_summary,location,required_by) VALUES(?,?,?,?,?,?)',[getUser(req).id,clinician_id,priority,text(case_summary),text(location),required_by]);await conn.execute("INSERT INTO notifications(user_id,channel,message,status) VALUES(?,'whatsapp',?,'queued')",[clinician_id,`EMERGENCY RECALL #${r.insertId} (${priority}). Location: ${text(location)}. Required by: ${required_by}. Log into Azman HealthConnect to review clinical case and accept or reject.`]);await conn.execute('INSERT INTO app_notifications(user_id,title,body,category,target_url) VALUES(?,?,?,?,?)',[clinician_id,'Emergency recall',`A ${priority} priority emergency recall has been assigned. Review the emergency queue immediately.`,'emergency','/clinical-console']);await conn.commit();await audit(req,'emergency_created','emergency',r.insertId,{priority});res.status(201).json({id:r.insertId,status:'pending',whatsapp:'queued_not_sent'})}catch(e){await conn.rollback();throw e}finally{conn.release()}}));
