if(require.main===module)app.listen(Number(process.env.PORT||3000),()=>console.log('Azman HealthConnect listening on '+(process.env.PORT||3000)));
module.exports=app;
const MEDICAL_DEPARTMENTS = new Set(['GOPD','Paediatrics','Diabetes / Endocrinology','Gynaecology','Internal Medicine','Family Medicine','Dermatology','Mental Health','Dental','Laboratory','ENT','Surgery','Ophthalmology','Emergency','Radiology','Anaesthesia','Medical Ward','Surgical Ward','Maternity Ward','Children\'s Ward','Eye Clinic','Dental Clinic','ENT Clinic','Emergency Unit','Intensive Care Unit (ICU)']);
function isMedicalDepartment(value){return MEDICAL_DEPARTMENTS.has(String(value||'').trim());}


